-- exmd4-5.hs: extended Minsky doubling (value x4, 5 cycles)
-- Start: (0, 0, 0). Goal: (0, 0, 1). The value reaches 4^5 = 1024.
-- Generated by make-exmd.py.  Feed through hs2maze.py to obtain the maze.

exmd :: (Int, Int, Int) -> (Int, Int, Int)

-- Phase 0 (pc=0): y := 1
exmd (x, y,    0) = exmd (  x, y+1,    2)

-- Cycle 0 (pc=2): y -> x, x4
exmd (x, 0,    2) = exmd (  x,   0,    7)
exmd (x, y,    2) = exmd (  x, y-1,    3)
exmd (x, y,    3) = exmd (x+1,   y,    4)
exmd (x, y,    4) = exmd (x+1,   y,    5)
exmd (x, y,    5) = exmd (x+1,   y,    6)
exmd (x, y,    6) = exmd (x+1,   y,    2)

-- Cycle 1 (pc=7): x -> y, x4
exmd (0, y,    7) = exmd (  0,   y,   12)
exmd (x, y,    7) = exmd (x-1,   y,    8)
exmd (x, y,    8) = exmd (  x, y+1,    9)
exmd (x, y,    9) = exmd (  x, y+1,   10)
exmd (x, y,   10) = exmd (  x, y+1,   11)
exmd (x, y,   11) = exmd (  x, y+1,    7)

-- Cycle 2 (pc=12): y -> x, x4
exmd (x, 0,   12) = exmd (  x,   0,   17)
exmd (x, y,   12) = exmd (  x, y-1,   13)
exmd (x, y,   13) = exmd (x+1,   y,   14)
exmd (x, y,   14) = exmd (x+1,   y,   15)
exmd (x, y,   15) = exmd (x+1,   y,   16)
exmd (x, y,   16) = exmd (x+1,   y,   12)

-- Cycle 3 (pc=17): x -> y, x4
exmd (0, y,   17) = exmd (  0,   y,   22)
exmd (x, y,   17) = exmd (x-1,   y,   18)
exmd (x, y,   18) = exmd (  x, y+1,   19)
exmd (x, y,   19) = exmd (  x, y+1,   20)
exmd (x, y,   20) = exmd (  x, y+1,   21)
exmd (x, y,   21) = exmd (  x, y+1,   17)

-- Cycle 4 (pc=22): y -> x, x4
exmd (x, 0,   22) = exmd (  x,   0,   27)
exmd (x, y,   22) = exmd (  x, y-1,   23)
exmd (x, y,   23) = exmd (x+1,   y,   24)
exmd (x, y,   24) = exmd (x+1,   y,   25)
exmd (x, y,   25) = exmd (x+1,   y,   26)
exmd (x, y,   26) = exmd (x+1,   y,   22)

-- Drain (pc=27): DEC x to 0, then HALT
exmd (0, y,   27) = (  0,   y,    1)
exmd (x, y,   27) = exmd (x-1,   y,   27)
